ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_14"] = {
{"s12_tracks_small_feet_017","any",2,"reg=family,rescue|tmp=fresh,seasoned|hour=7,11|mood=fear|world=door,building",{1,"There's a child's footprint in the flour by the pantry door",2,"How big?",1,"Small, four, five year old - both of ours are eleven and thirteen and both of 'em was asleep by me"}},
{"s12_tracks_deer_stand_018","any",2,"reg=civilian,worker|tmp=seasoned|hour=5,9|mood=grim",{1,"Somebody's been sitting in my deer stand, cigarette butts, six of 'em, lined up on the rail",2,"Hunters",1,"That stand looks at my back door, ain't a deer trail within four hundred yard of it"}},
{"s12_tracks_scarecrow_moved_019","any",2,"reg=family,civilian|tmp=seasoned|hour=7,12|mood=fear",{1,"That scarecrow's about fifteen foot closer to the house than where I set it",2,"Kids messing with you",1,"There's a new post hole under it, dug and tamped - whoever moved it brought a shovel"}},
{"s12_tracks_no_flies_020","any",2,"reg=rescue,law|tmp=seasoned|mood=grim|world=road",{1,"There's a dead one in that ditch off Halbert been there a week, and there's no flies on it",2,"Heat should have it crawling",1,"Heat should have it crawling, I walked a half mile out of my way on the road home"}},
{"s12_tracks_feed_disappears_021","any",2,"reg=worker,family|tmp=seasoned|mood=grim",{1,"Somebody's taking a coffee can of corn out of the crib every night - one can",2,"Coon",1,"Coon don't put the lid back on the can and set it where it was"}},
{"s12_tracks_garden_watered_022","any",2,"reg=family,civilian|tmp=seasoned|hour=6,10|mood=fear|world=water",{1,"Garden's been watered, rows are wet, ground's dark, and it ain't rained since Sunday",2,"Hauled from the creek?",1,"Creek's two hundred yards down a hill, that's a lot of buckets to carry for somebody else's beans"}},
{"s12_tracks_the_same_woman_024","any",3,"reg=civilian,family|tmp=seasoned|hour=18,21|mood=grim|world=fence",{1,"Same woman goes past our fence about six every evening - dead as they come",2,"Then put her down and quit talking about her",1,"She never turns her head, not one time, not in eleven evenings",3,"They don't turn their heads",1,"They all turn their heads, every one of 'em turns their head at a fence with people behind it"}},
{"s12_tracks_count_goes_up_025","any",2,"reg=civilian,worker|tmp=seasoned|hour=17,21|mood=fear",{1,"Nineteen of 'em stood in the Yeager field Monday - twenty Tuesday, twenty one today",2,"They wander in",1,"I know every face out there now, that's the part I can't put down - I know all twenty one"}},
{"s12_tracks_quiet_crowd_026","any",2,"reg=law,rescue|tmp=seasoned|mood=grim|world=vehicle,door",{1,"Whole school lot full of 'em, forty, maybe more, not one making a sound",2,"Facing what?",1,"The gym doors, all of 'em - I backed the car out with the engine off and let it roll"}},
{"s12_tracks_gate_latched_027","any",2,"reg=family,civilian|tmp=seasoned|hour=6,10|mood=fear",{1,"Garden gate was latched this morning and I never latch that gate",2,"Then one of us latched it",1,"I asked all four of you and all four of you said no, and I believe all four of you - that's my trouble"}},
{"s12_tracks_no_smoke_028","any",2,"reg=civilian,worker|tmp=seasoned|hour=6,10|mood=grim|world=door,summer",{1,"Twenty houses down in that hollow, every door shut, not a chimney going",2,"Summer - who's lighting a fire in summer?",1,"It was down to fifty two that morning and everybody in there's cooking on wood - somebody'd light something"}},
{"s12_tracks_road_was_moving_029","any",3,"reg=civilian,worker|tmp=seasoned|hour=7,11|mood=fear|world=stairs,road",{1,"From up on the water tower you can see 31W clear to the Valley Station side",2,"And?",1,"The road was moving - south, the road was",3,"How wide",1,"Both lanes and the shoulders, I come down the ladder faster than I went up it"}},
{"s12_tracks_lights_in_order_031","any",2,"reg=civilian,worker|tmp=seasoned|hour=22,3|mood=grim|world=building",{1,"I watched the city go dark off the roof of the barn - it wasn't all at once",2,"Grid drops in sections",1,"Block by block, north to south, even time between, something was walking it"}},
{"s12_tracks_hedge_boots_032","any",2,"reg=civilian,worker|tmp=seasoned|hour=6,11|mood=fear",{1,"I ain't saying it was a man in the garden - I'm saying it had boots on",2,"Boots and a shovel, then",1,"Boots, and it knew to step in the row and not on the plants - that's the part I keep going back to"}},
{"s12_tracks_proof_object_033","any",2,"reg=civilian,family|tmp=seasoned|mood=fear|world=fence",{1,"I still got the sock I found on the fence wire - you want to see it? I'll go get it",2,"Just tell me about it",1,"Child's sock, clean, and there ain't been a child on this place since the Pruitts sold in eighty eight"}},
{"s12_tracks_draft_witness_034","any",2,"reg=family,civilian|tmp=seasoned|hour=7,12|mood=grim",{1,"You've kept a garden, you know how dirt looks when a thing's been drug across it",2,"I do",1,"Then come look at my melon patch and tell me what got drug and which way it went"}},
{"s12_tracks_refuse_name_035","any",2,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=fear",{1,"It wasn't one of them, I'll say that much and stand on it",2,"Then what was it?",1,"Something, I'm going to call it a fella and you're going to let me call it a fella"}},
{"s12_tracks_kid_question_036","any",2,"reg=family|tmp=fresh|hour=19,23|mood=sad",{1,"The boy asked me who's been helping in the garden",2,"What'd you say?",1,"I said a neighbor, he said which one and I said one you ain't met - that was the wrong answer"}},
{"s12_tracks_predator_takes_037","any",2,"reg=raider,outlaw|tmp=predator|mood=grim",{1,"I watched a garden on Piney Fork once. Watered, weeded, staked up proper",2,"You'd think there were people in the house",1,"I watched two nights without seeing anybody. Couldn't tell who was tending it",2,"Somebody could have come while you weren't looking",1,"Could have. That's what I kept telling myself"}},
{"s12_tracks_worker_reads_038","any",2,"reg=worker|tmp=seasoned,veteran|mood=calm",{1,"I read sign for thirty years, hogs and deer and men - them tracks are a man's",2,"So a man, then",1,"A man that weighs about ninety pound, that's what the depth says, and I don't like what the depth says"}},
{"s12_tracks_tracks_in_ashes_039","any",2,"reg=civilian,worker|tmp=seasoned|hour=6,10|mood=fear|world=fire",{1,"Somebody walked through our fire pit, prints right through the ash, edge to edge",2,"Cold ash?",1,"We banked that fire at eleven, that ash was live at three - there ain't a mark burnt into 'em"}},
{"s12_tracks_flat_close_040","any",2,"reg=civilian,family|tmp=seasoned|hour=7,11|mood=calm",{1,"So I raked the row out flat before dark so I'd know",2,"And this morning?",1,"Raked flat, just like I left it, nothing in it - and that was that"}},
{"s12_tracks_raked_then_new_041","any",3,"reg=civilian,family|tmp=seasoned|hour=6,10|mood=fear",{1,"Second night I raked it flat there was one print in the middle of the row",2,"One",1,"One, nothing coming in and nothing going out, just the one, dead center",3,"That's somebody having fun with you",1,"That would be a relief and I'd take it, I would - I don't think that's what it is"}},
{"s12_tracks_dog_barks_at_house_042","any",2,"reg=family,civilian|tmp=seasoned|hour=20,2|mood=fear|world=building",{1,"Blue's been barking at our own back bedroom for three nights",2,"There ain't nothing in that bedroom, we use it for flour",1,"Then come stand in the hall with me at eleven and we'll both know there ain't nothing in it"}},
{"s12_tracks_deputy_log_043","any",2,"reg=law|tmp=seasoned,veteran|mood=calm",{1,"I've got a prowler call from a house nobody's living in - third one from that address",2,"Who's calling it in? Phones are out",1,"Somebody writes it on the board at the office in the night - in printing, neat as a schoolteacher"}},
{"s12_tracks_creek_no_minnows_045","any",2,"reg=worker,civilian|tmp=seasoned|mood=grim|world=water",{1,"No minnows in the creek at the ford - none, I stood in it to my knees",2,"Water's low, they went to the deep holes",1,"That's probably right, it's the first time in my life I've been in that creek and had it be still"}},
{"s12_tracks_elite_report_046","any",2,"reg=elite|tmp=veteran|mood=calm|world=trees",{1,"Sign at the tree line, one set in, one set out, bare feet, same size",2,"Time separation?",1,"Dew says four hours apart, whoever it is went in, waited, and came back out on a schedule"}},
{"s12_tracks_scared_trainee_047","any",2,"reg=military|role=soldier_green,soldier_nco|tmp=fresh,veteran|hour=1,5|mood=fear",{1,"Sergeant, there's prints on the inside of the wire, inside, not outside",2,"Show me in the morning",1,"I'd rather show you now, if that's alright, I'd rather not be the only one that's seen 'em",2,"Alright, get a light - walk behind me and don't step where I step"}},
{"s12_tracks_two_dogs_048","any",2,"reg=civilian,family|tmp=seasoned|mood=sad|world=vehicle",{1,"Both dogs sit at the end of the drive at four thirty - every day",2,"Waiting on what?",1,"School bus, bus ain't run since the sixth, they still go out there and sit"}},
{"s12_tracks_downgrade_049","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=fear|world=building",{1,"Probably somebody's dog got in the corn, probably that's all it is",2,"A dog",1,"A dog, I moved the shotgun to the kitchen side of the bed, but yeah - probably a dog"}},
{"s12_tracks_rule_at_end_050","any",2,"reg=family,civilian,worker|tmp=seasoned|mood=grim|world=trees",{1,"New rule, nobody picks in that garden after supper, morning only, two people, one watching the trees",2,"On account of the tracks",1,"On account of the tracks - morning only - two people"}},
{"s12_wave_too_late_001","any",2,"reg=civilian,family|tmp=seasoned|hour=17,21|mood=fear",{1,"Hobart waved at me from his porch this evening",2,"Well, good, I figured he was gone",1,"I was near past his drive before he done it - like it took a while to get to him"}},
{"s12_wave_every_evening_002","any",2,"reg=civilian,worker|tmp=seasoned|hour=18,21|mood=grim",{1,"I've waved at that man every evening for eleven years - he always beat me to it",2,"So?",1,"Now he waits - every time, waits till my hand's already down"}},
{"s12_wave_wrong_hand_003","any",3,"reg=civilian,family|tmp=seasoned|hour=17,20|mood=fear|world=road",{1,"Verna's out at the clothesline waving with her left",2,"And?",1,"Verna ain't got a left, lost it in a corn picker in seventy six - everybody on this road knows that",3,"You seen wrong",1,"I've been looking at that woman's sleeve pinned up since I was a boy - I did not see wrong"}},
{"s12_wave_didnt_blink_004","any",2,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=fear",{1,"Fella sat at our fire, ate what we gave him, talked about the weather like a person",2,"Sounds fine to me",1,"Hour and a half and he never blinked, not one time, I watched for it after the first ten minutes"}},
{"s12_wave_half_second_005","any",2,"reg=civilian,family|tmp=seasoned|hour=19,1|mood=fear",{1,"You'd ask him a thing and he'd answer about a half second late",2,"Man's hard of hearing",1,"Every question - same gap, even the easy ones, even his own name"}},
{"s12_wave_fixed_his_face_006","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim",{1,"I told him about my brother on the bridge - he smiled",2,"Some folks don't know what to do with their face",1,"Then he fixed it, I watched him fix it, that's different from not knowing what to do"}},
{"s12_wave_knows_the_dog_007","any",2,"reg=civilian,family|tmp=seasoned|hour=18,23|mood=fear",{1,"He asked after my dog - by name",2,"You must have said it",1,"I never said one word about having a dog, I've thought back through the whole conversation four times"}},
{"s12_wave_repeats_my_ending_008","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear",{1,"Whatever I said, he'd say the tail end of it back - quiet, under his breath",2,"Old boy's simple, maybe",1,"He wasn't simple, he was learning it, there's a difference and I felt the difference"}},
{"s12_wave_asks_about_water_009","any",3,"reg=civilian,family,worker|tmp=seasoned|mood=grim|world=fence",{1,"That fella at the fence asked three questions and every one of 'em was about the water",2,"Man's thirsty",1,"He didn't drink the cup I give him, held it the whole time and set it down full",3,"Well, that's poor manners",1,"It's poor manners, it's also the fourth stranger this month asked about our well and not our food"}},
{"s12_wave_neighbor_at_window_010","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=20,2|mood=fear|world=window",{1,"Somebody's been stood in the Kelso front window every night about ten",2,"Doyle never left, maybe",1,"Doyle's a big man, that shape in the window is a little one and it don't move at all"}},
{"s12_wave_wave_with_bad_arm_011","any",2,"reg=civilian,worker|tmp=seasoned|hour=17,21|mood=grim|world=building",{1,"I waved at the Tandy place out of habit, something up on the porch waved back",2,"At the shoulder or at the elbow?",1,"Shoulder, whole arm, stiff, like a kid's toy, and then it done it again about a minute later"}},
{"s12_wave_shirt_is_wrong_012","any",2,"reg=family,civilian|tmp=seasoned|mood=fear",{1,"That's Merle's shirt, I know that shirt, I've patched that shirt",2,"So Merle's alive",1,"That is not the shape of Merle inside of it - and that shirt's clean, and Merle has never been clean"}},
{"s12_wave_says_our_words_013","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,1|mood=fear",{1,"New fella used a saying of ours, 'root hog or die.' Said it right, too, with the pause in it",2,"Everybody says that",1,"Nobody says it the way my daddy said it, he said it the way my daddy said it"}},
{"s12_wave_smiles_at_the_dark_014","any",2,"reg=civilian,family|tmp=seasoned|hour=21,3|mood=fear",{1,"He sat facing away from the fire the whole time - faced out at the dark and talked to us over his shoulder",2,"Man's careful, I'd call that good sense",1,"Then he'd smile at something out there, not at us - that's what run me off to bed"}},
{"s12_wave_woman_on_the_road_015","any",2,"reg=civilian,worker|tmp=seasoned|hour=6,10|mood=grim",{1,"Woman walking the shoulder of 31W with a purse on her arm - waved me down",2,"You stop?",1,"I slowed, her shoes was on the wrong feet and she was walking real good on 'em anyhow"}},
{"s12_wave_children_on_porch_016","any",3,"reg=civilian,family|tmp=seasoned|hour=16,20|mood=fear|world=building",{1,"There's two kids sitting on the Six porch steps of an evening",2,"Then somebody's got kids alive over there and we ought to go see about 'em",1,"I hollered at 'em Tuesday",3,"And?",1,"They both turned their heads at the same time, exactly the same time, I'll go with you, but not at night"}},
{"s12_wave_mirror_habit_017","any",2,"reg=civilian,worker|tmp=seasoned|mood=fear",{1,"He did everything I did, I'd cross my arms, he'd cross his - I'd lean, he'd lean",2,"Folks do that when they want you to like 'em",1,"I know, I put my hand flat on my head just to see - he put his hand flat on his head"}},
{"s12_wave_no_sweat_018","any",2,"reg=worker,civilian|tmp=seasoned|hour=12,17|mood=fear|world=road",{1,"Ninety eight out there and that man is dry as a bone - long sleeves, buttoned at the wrist",2,"Some folks don't sweat much",1,"Everybody sweats in this, I've got a shirt I could wring out, he come off that road dry"}},
{"s12_wave_asks_how_many_019","any",2,"reg=civilian,family|tmp=seasoned|mood=grim",{1,"They come by with seed corn and they ask how many rifles we've got",2,"Just conversation",1,"Every time, same question, different fella - nobody's asked how many of us there is"}},
{"s12_wave_gate_guard_020","any",3,"reg=law,swat|tmp=veteran|mood=calm",{1,"Hold it right there, show me your hands, both of 'em",2,"He's showing 'em - look at the hands",1,"I am looking at the hands - Sir, how many with you? Anybody hurt? Anybody bit?",3,"He answered all three in the same order you asked 'em - word for word order",1,"Lay the long gun down and step off it, then wait there - somebody's coming out to you"}},
{"s12_wave_wrong_name_for_town_021","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim",{1,"He said he was from up the county and then he called Muldraugh by the wrong name",2,"What'd he call it?",1,"He called it the right name, just not the one anybody living here uses, nobody says the whole thing"}},
{"s12_wave_borrowed_grief_022","any",2,"reg=civilian,family|tmp=seasoned|mood=sad",{1,"He told me he lost his wife and his girl - said it flat, then asked to be let on his way",2,"That's about the saddest thing a man can say",1,"Two days later a different fella at the bridge said it to me in the same words - same order, same okay at the end"}},
{"s12_wave_neighbor_mowed_024","any",2,"reg=civilian,worker|tmp=seasoned|hour=17,21|mood=grim",{1,"Somebody's keeping the Dees yard mowed, edges done and all",2,"Truett always kept it nice",1,"Truett's in the ditch at the end of his own drive - been there since the eleventh, yard's still nice"}},
{"s12_wave_same_clothes_025","any",2,"reg=civilian,family|tmp=seasoned|mood=fear|world=fence",{1,"That fella's come to the fence four times in three weeks in the exact same clothes",2,"So has everybody, ain't a washer running in this county",1,"Same clothes and the same dirt on 'em, same spot on the knee, same place on the collar - it don't move"}},
{"s12_wave_stares_at_child_026","any",2,"reg=family|tmp=fresh,seasoned|hour=16,20|mood=fear",{1,"He was real kind and he asked good questions and he never once looked at the baby",2,"That's what you'd want, ain't it?",1,"She was crying, there is nobody alive that don't look at a crying baby - not for ten whole minutes"}},
{"s12_wave_wrong_church_027","any",2,"reg=rescue,family|tmp=seasoned|mood=grim",{1,"He knew the hymn numbers at Little Bethel, knew which pew was the Kelsos'",2,"Then he's a member, I don't see the trouble",1,"I've preached that church nineteen years, I have never in my life seen that man's face"}},
{"s12_wave_answers_before_028","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,1|mood=fear",{1,"Twice he answered before I finished asking, not cutting in - answering",2,"Man's quick",1,"The second one was a question I'd only got the first two words out of"}},
{"s12_wave_predator_reads_029","any",2,"reg=raider,gang,crime|tmp=predator|mood=grim|world=building",{1,"That one on the porch don't act right, I've robbed about forty houses and I know how folks act",2,"He's scared, that's all",1,"Scared men look at the gun, he looked at my boots and then at my hands and then he smiled",2,"So we take the house",1,"We take the shed and we go, I ain't going in a house behind a man that smiles at hands"}},
{"s12_wave_veteran_notes_030","any",2,"reg=military,elite|tmp=veteran|mood=calm",{1,"Subject answered the challenge correctly, cadence was off",2,"Off how, Sergeant?",1,"Like he'd read it, nobody who's lived the words says 'em that even - keep him outside the wire"}},
{"s12_wave_returns_the_favor_031","any",2,"reg=civilian,family|tmp=seasoned|mood=warm|world=fence",{1,"Stranger hauled me over that fence by my belt and give me his own canteen",2,"He take anything?",1,"Wouldn't take my name, didn't want thanks, I never got his, and it's been eating at me since"}},
{"s12_wave_neighbor_real_032","any",2,"reg=civilian,family|tmp=seasoned|hour=17,20|mood=warm|world=vehicle,door",{1,"Arlis waved me down and put a sack of squash in the truck and told me to shut the door",2,"He say anything else?",1,"He said tell your mama I asked after her, which is the first ordinary sentence I've heard in a week"}},
{"s12_wave_hedge_claim_033","any",2,"reg=civilian,worker|tmp=seasoned|hour=18,23|mood=fear|world=building",{1,"I ain't saying that wasn't Hobart on the porch, I'm saying Hobart's got a limp",2,"And it didn't limp",1,"It went down them three steps like a young man - that's every bit of what I know"}},
{"s12_wave_restart_034","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=20,2|mood=fear|world=building",{1,"So we come up the drive, and he's on the steps - no, back up, he was at the mailbox first",2,"Alright, the mailbox",1,"At the mailbox, and then he was on the steps, and I never saw him cover that ground"}},
{"s12_wave_draft_witness_035","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim|world=fence",{1,"You've known Glenda your whole life, you know how she laughs",2,"I do",1,"Then you come stand at that fence at six o'clock and listen to what's laughing in her kitchen"}},
{"s12_wave_refuse_to_name_036","any",2,"reg=civilian,family|tmp=seasoned|hour=21,3|mood=fear",{1,"I ain't got a word for what waved at me - it wasn't one of them, they don't wave",2,"Then it was a person",1,"I'll say it was a neighbor, that's the word I'm going to use and I'd like to leave it there"}},
{"s12_wave_apologize_037","any",2,"reg=civilian,worker|tmp=seasoned|hour=23,4|mood=fear",{1,"I know it's late, I shouldn't be laying this on you with you up at four",2,"Say it and then we'll both sleep",1,"The man that come to the gate today is the man I helped bury on the fourteenth - that's all - goodnight"}},
{"s12_wave_coda_rule_038","any",2,"reg=civilian,family,worker|tmp=seasoned|mood=grim",{1,"So we don't wave at porches no more, not on Tanner, not on Bethel Ridge, eyes front, keep driving",2,"That's a hard way to live next to folks",1,"It is - eyes front"}},
{"s12_wave_downgrade_039","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=fear|world=road",{1,"Probably just a fella squatting in Hobart's house and wearing Hobart's clothes - that's probably it",2,"That's probably it",1,"I quit going down that end of the road, but yeah - probably that"}},
{"s12_wave_flat_end_040","any",2,"reg=civilian,family|tmp=seasoned|mood=calm",{1,"So he waved, and I drove on, and he was still stood there in the mirror till the curve",2,"And then?",1,"And then the curve - that's it, that's all there was"}},
{"s12_wave_gallows_041","any",2,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=funny",{1,"Most polite conversation I've had since the fourth was with something that don't blink, hahaha",2,"Heh - well",1,"It asked after my mother, I wonder how it knew I had one"}},
{"s12_wave_kid_noticed_042","any",2,"reg=family|tmp=fresh|hour=18,22|mood=fear|world=fence",{1,"A girl once told me a man at a fence had no shadow",2,"Kids say things",1,"She'd noticed things we'd missed before. Didn't make it proof, but I listened"}},
{"s12_wave_prison_read_043","any",2,"reg=prison,outlaw|tmp=predator,seasoned|mood=grim|world=door",{1,"I spent eleven years learning to tell what a man is by how he stands in a doorway",2,"And?",1,"That one at the gate stood in it like furniture - didn't shift his weight one time in ten minutes"}},
{"s12_wave_rescue_triage_044","any",3,"reg=rescue|tmp=seasoned,veteran|mood=calm",{1,"Pulse is fine, pupils are fine - he answers every question I ask him",2,"Then what's got you standing there with the bag still shut?",1,"He answers 'em all the same way, same tone, same speed, whether I ask his name or where it hurts",3,"Ask him something with no answer",1,"I did, I asked what color Tuesday is, he said the same way he said his name, let's work outside"}},
{"s12_wave_letter_of_intro_046","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim",{1,"He brought a note from Earl saying to let him in - Earl's hand, Earl's spelling, Earl's little E",2,"Then let him in",1,"Earl can't write since the stroke, he signs with an X and everybody in three counties knows it"}},
{"s12_wave_asks_to_be_let_go_047","any",2,"reg=civilian,family|tmp=fresh|hour=17,22|mood=sad",{1,"He wouldn't come in, he said he'd sooner keep on to his sister's at Rosewood before dark",2,"You let him go?",1,"I give him water and I let him go his way - he said please, and then thank you, and then he said it again"}},
{"s12_wave_neighbor_writes_048","any",2,"reg=civilian,family|tmp=seasoned|hour=8,12|mood=grim|world=window",{1,"Somebody's been washing the Kelso windows, front three, from the outside",2,"Then somebody's proud of that house",1,"From the outside, Wanda, which means somebody stood out in that yard looking in at nothing for an hour"}},
{"s12_wave_i_waved_first_049","any",2,"reg=civilian,worker|tmp=seasoned|hour=18,22|mood=fear|world=vehicle",{1,"Here's the part I can't put down, I waved first",2,"So?",1,"So now it knows what a wave is, and it knows which truck I drive, and it knows what time I come by"}},
{"s12_wave_answer_other_q_050","any",2,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=fear|world=door,building",{1,"Did he follow you home, is what I'm asking you",2,"There was a smell off him, like a cellar, like turned dirt - right up close and then gone",1,"Not what I asked, and you know it",2,"I know it - go on and latch the back door and then ask me again"}},
{"s1_army_long_beep_001","any",2,"reg=civilian,family|tmp=fresh|day=2,6|mood=grim",{1,"TV did that long beep again",2,"Anything new?",1,"Same crawl across the bottom, remain in your homes - await instructions",2,"We've been awaiting since Sunday, I've about awaited myself to death"}},
{"s1_army_trucks_north_002","any",3,"reg=civilian,family|tmp=fresh|day=0,3|hour=7,18|mood=fear|world=cars",{1,"Army trucks going up 31W, must've been thirty of them - headlights on in broad daylight",2,"Did they stop in town?",1,"Didn't even slow down for the light at the Dairy Bar",3,"Then they're not coming for us, they're going somewhere worse"}},
{"s1_army_bedsheet_wave_003","any",2,"reg=family|tmp=fresh|day=1,10|mood=sad",{1,"The kids ran out waving the bedsheet when the helicopter went over",2,"Did it turn?",1,"Kept right on toward Fort Knox - Emma waved till she couldn't hear it anymore"}},
{"s1_army_louisville_go_004","any",3,"reg=family|tmp=fresh|day=0,4|hour=16,5|mood=angry|world=vehicle",{1,"Louisville's got the big hospitals, the Army's there, we load the van and we go tonight",2,"Everybody in three counties is thinking the same thing right now",3,"So we sit here and wait to get eaten because there might be traffic?",2,"I'm saying there might be traffic full of them - yes"}},
{"s1_army_station_dead_005","any",2,"reg=civilian,family|tmp=fresh|day=3,8|mood=fear",{1,"Louisville AM station just went off, middle of the fella talking",2,"Try the FM",1,"I've tried every number on the dial twice, there's one preacher and a lot of hiss",2,"Leave it on the preacher, then - low"}},
{"s1_army_west_point_bridge_006","any",3,"reg=civilian|tmp=fresh|day=1,6|mood=angry|world=vehicle",{1,"My cousin tried to cross at West Point, soldiers turned him right around",2,"Did they say why?",1,"Some kid with a rifle, couldn't be nineteen, just kept saying sir, turn it around",3,"Nineteen years old and he's the whole government now"}},
{"s1_army_guard_brother_007","any",2,"reg=family|tmp=fresh|day=1,10|mood=warm",{1,"Donnie's in the Guard, if they've called him up, he'll get word to us somehow",2,"Donnie can't find his own truck keys",1,"He found me at the county fair when I was six and lost - walked the whole midway hollering",2,"True, Donnie'll find us"}},
{"s1_army_jets_boom_008","any",3,"reg=civilian,family|tmp=fresh|day=2,10|mood=fear|world=window,water",{1,"Did you feel that? The windows shook",2,"Jets - sonic boom",3,"That wasn't a boom from up high, I felt it in the floor",1,"From which way?",3,"North, toward the river"}},
{"s1_army_flag_hour_009","any",2,"reg=civilian,family|tmp=fresh|day=2,5|mood=grim",{1,"They said the President would come on at eight",2,"And?",1,"They showed a flag, a flag waving, for an hour and ten minutes - then the colored bars"}},
{"s1_army_gold_eat_010","any",3,"reg=civilian|tmp=fresh|day=2,14|mood=funny|world=building",{1,"Whole Army sitting over at Knox guarding a basement full of gold",2,"Gold's worth something",3,"Not to me, you can't fry it, you can't put it in a sandwich",1,"Hard to hit a dead guy with, too - too heavy"}},
{"s1_army_gym_rumor_011","any",3,"reg=civilian|tmp=fresh|day=1,6|world=road",{1,"Lady down the road heard there's a relief center at the high school gym in Brandenburg - cots, water, doctors",2,"Heard from who?",1,"From her sister, who heard it on the scanner",3,"So a scanner told a sister told a lady, I'll pack a bag but I won't unpack hope"}},
{"s1_army_fence_posts_012","any",2,"reg=civilian|tmp=fresh|day=2,8|mood=fear|world=fence,road",{1,"They're putting up fence out along the highway past the county line - posts every ten feet",2,"To keep them things in",1,"Or to keep us in with them, the wire's on our side of the posts"}},
{"s1_army_rabbit_ears_013","any",3,"reg=family|tmp=fresh|day=5,14|mood=funny",{1,"Hold the rabbit ears right there - no, back - there!",2,"How long do I have to stand like this?",3,"Till something comes on besides fuzz",2,"I'm going to be a TV antenna for the rest of my life"}},
{"s1_army_sermon_loop_014","any",2,"reg=civilian,family|tmp=fresh|day=4,14|hour=18,23|mood=calm|world=trees",{1,"That preacher station's playing the same sermon again, third time today",2,"Somebody put it on a loop and left",1,"I've got the part about the fig tree memorized, I know when he coughs"}},
{"s1_army_test_theory_015","any",3,"reg=civilian|tmp=fresh|day=1,14|mood=angry|world=fence,building",{1,"Army cooked this up at Knox, some germ test, now they're fencing us in so nobody talks",2,"Why would they test it next door to their own base?",1,"Because they figured they'd get it right!",3,"Doesn't matter who made it, doesn't change how many are in the yard"}},
{"s1_army_scanner_deputies_016","any",2,"reg=civilian,family|tmp=fresh|day=0,4|hour=18,4|mood=fear",{1,"Turn up the scanner, that's a deputy",2,"He's asking for any units near Riverside, anybody at all",1,"Nobody's answering him",2,"He just said his unit number again, real quiet this time"}},
{"s1_army_red_flares_017","any",3,"reg=civilian,family|tmp=fresh|day=2,12|hour=21,4|mood=fear",{1,"Come look, red flares, out over toward the base",2,"That's a signal - somebody's signaling",3,"Signaling what?",2,"I don't know, I sold carpet - somebody who knows is signaling somebody else who knows"}},
{"s1_army_door_list_018","any",2,"reg=family|tmp=fresh|day=2,10|mood=warm|world=door",{1,"When they come it'll be door to door with a clipboard, names and head counts",2,"How do you know that?",1,"That's how they did it after the flood of seventy-eight - a soldier gave me a chocolate bar out of his pocket",2,"Well, I'll have our names written down ready, then"}},
{"s1_army_tuned_flat_019","any",2,"reg=civilian|tmp=fresh|day=3,12|mood=funny",{1,"Stay tuned for further instructions, it says",2,"How long we been tuned now?",1,"Long enough that if they don't hurry up I'm gonna go flat"}},
{"s1_army_road_atlas_020","any",3,"reg=family|tmp=fresh|day=1,10|mood=calm|world=water,road",{1,"Get the road atlas out of the glovebox, the good one, not the gas station map",2,"Dixie Highway's no good, everybody's on it",3,"Back roads through Fallas Lake, then up along the river?",1,"That's a lot of back roads with a quarter tank - get a pencil"}},
{"s1_army_walked_back_021","any",2,"reg=civilian,family|tmp=fresh|day=3,9|hour=4,11|mood=grim",{1,"The Greers left for Louisville on Saturday, loaded up the boat and everything",2,"Good for them",1,"Ron Greer walked back into town this morning - by himself, no boat, no shoes",2,"What'd he say?",1,"Nothing, he sat down on his porch, he's still sitting"}},
{"s1_army_indiana_boat_022","any",3,"reg=civilian|tmp=fresh|day=2,14|world=water",{1,"Indiana's right there across the river, we find a jon boat and we row",2,"And when they see a boat from the Kentucky side?",1,"They'd shoot at a boat full of families?",3,"Somebody on the scanner said they already did, out by Brandenburg"}},
{"s1_army_leaflets_023","any",2,"reg=civilian,family|tmp=fresh|day=3,9|mood=funny",{1,"Plane dropped papers all over the ball field, printed and everything",2,"What do they say?",1,"Remain in your homes, do not approach the checkpoints - have a nice day",2,"It doesn't say have a nice day",1,"It might as well"}},
{"s1_army_mutter_static_024","any",1,"reg=civilian,family|tmp=fresh|day=5,14|hour=19,3|mood=sad|world=vehicle",{1,"Come on, somebody - anybody out there",1,"I'd take a car commercial, I'd take the farm report",1,"I'd listen to hog prices all night long, I swear I would"}},
{"s1_army_gunfire_far_025","any",3,"reg=civilian|tmp=fresh|day=1,14|mood=fear",{1,"Hear that? Gunfire, lots of it, out east",2,"That's the Army working - that's good",3,"Or that's somebody's last stand in a Methodist church",2,"Why can't you ever let me have one thing?"}},
{"s1_army_all_circuits_026","any",2,"reg=family|tmp=fresh|day=0,4|mood=sad",{1,"I tried Mom again, all circuits are busy, please try your call again later",2,"How many times?",1,"I quit counting, I know the recording lady's voice better than my own mother's now"}},
{"s1_army_trucker_cb_027","any",3,"reg=civilian|tmp=fresh|day=1,6|mood=fear",{1,"Trucker on channel nineteen says they've got the interstate shut at both ends - concrete barriers",2,"Both ends of what?",1,"Of us, I think, both ends of us",3,"Did he say anything else?",1,"Said keep the shiny side up, then he was gone"}},
{"s1_army_well_water_028","any",2,"reg=family|tmp=fresh|day=2,14|mood=calm|world=building",{1,"We stay, we've got the well, the garden, the root cellar, the city folks have a faucet",2,"And when the pump needs power?",1,"Daddy's old hand pump is in the barn, I'll grease it up tomorrow",2,"Grease it today"}},
{"s1_army_shooting_rumor_029","any",3,"reg=civilian|tmp=fresh|day=3,12|mood=angry",{1,"Folks are saying the soldiers are shooting anybody who walks up to the line - even with their hands up",2,"American soldiers wouldn't",3,"American soldiers who are scared out of their minds and been told to hold a line?",2,"I still don't believe it",1,"Then you walk up and wave"}},
{"s1_army_weatherman_030","any",2,"reg=civilian,family|tmp=fresh|day=2,5|mood=funny",{1,"The weatherman came on channel eleven, still doing the weather",2,"What's he calling for?",1,"Hot and humid, chance of storms, then he took his tie off on the air and walked out of the shot"}},
{"s1_army_roof_help_031","any",3,"reg=family|tmp=fresh|day=3,12|mood=warm|world=building,rooftop",{1,"We painted HELP on the roof in white house paint - letters six feet tall",2,"And four kids here, like they're gonna count",3,"We ran out of paint on the four, so it's HELP and a real skinny line",1,"They'll figure it out"}},
{"s1_army_hovered_032","any",2,"reg=civilian|tmp=fresh|day=2,12|mood=grim",{1,"That helicopter hung right over the Baptist church a full minute - just hovering",2,"Looking for survivors?",1,"Counting something, maybe, then it went off toward Rosewood and didn't come back"}},
{"s1_army_bag_by_door_033","any",2,"reg=family|tmp=fresh|day=2,10|mood=calm|world=door",{1,"Everybody keeps one bag by the door, clothes, medicine, a picture if you want one",2,"What's the picture for?",1,"In case we have to go fast and never come back to the house - pick one you like"}},
{"s1_army_jets_on_time_034","any",3,"reg=civilian|tmp=fresh|day=4,14|hour=6,10|mood=funny",{1,"There go the jets - seven-fifteen",2,"Same as yesterday",3,"Least something in this county still runs on time",1,"Wish they'd drop coffee"}},
{"s1_army_korea_grandpa_035","any",2,"reg=family|tmp=fresh|day=2,14|mood=grim",{1,"Grandpa won't talk about the Army coming, he just shakes his head",2,"He was in Korea",1,"He said an army goes where it's told, and nobody tells it to go get the Hutchins family first"}},
{"s1_army_anchor_cried_036","any",2,"reg=civilian,family|tmp=fresh|day=2,5|mood=sad",{1,"That lady anchor in Louisville cried on the air last night - the one with the big hair",2,"She did not",1,"She was reading the list of shelters and she just stopped and put her hand over her mouth",2,"Did she finish the list?",1,"Weatherman came and finished it for her"}},
{"s1_army_forty_eight_037","any",2,"reg=civilian|tmp=fresh|day=6,14|mood=angry|world=building",{1,"They said forty-eight hours - help within forty-eight hours",2,"When was that?",1,"Last Sunday, I wrote the time on the wall right there - that's a lot of forty-eights"}},
{"s1_army_loudspeaker_038","any",3,"reg=family|tmp=fresh|day=0,2|mood=fear",{1,"Sheriff's car just came through with the loudspeaker - stay in your homes, lock your doors",2,"Did they say what's going on?",1,"Said civil disturbance, then somebody ran out of the Moores' house and the deputy just kept driving",3,"Kept driving?",1,"Sped up, actually"}},
{"s1_army_everywhere_039","any",3,"reg=civilian|tmp=fresh|day=3,14|hour=20,2|mood=grim|world=fence",{1,"What if it's not just Knox County? What if it's the whole country?",2,"Then who's putting up the fences?",3,"Maybe everybody's putting up fences, every county fencing off every other county",1,"Well thanks a lot, now I'll sleep like a baby"}},
{"s1_army_test_pattern_040","any",2,"reg=family|tmp=fresh|day=5,14|mood=sad",{1,"She's watching the colored bars again",2,"There's nothing on",1,"She says the hum sounds like the TV's still thinking - so she's waiting for it to finish"}},
{"s1_army_city_glow_041","any",3,"reg=civilian,family|tmp=fresh|day=3,12|hour=21,4|mood=fear|world=window",{1,"Sky's orange up north and it's eleven at night, that ain't sunset",2,"Louisville",3,"How much of Louisville does it take to light up the sky from here?",2,"Don't think about it, come away from the window"}},
{"s1_army_cure_rumor_042","any",3,"reg=civilian|tmp=fresh|day=4,14|world=water",{1,"Man at the creek says they've got a shot for it at the base - only for soldiers so far",2,"How's he know?",1,"His nephew's a cook at Knox",3,"A cook, if they had a shot, the cook would be the last to know and the first to lie about it"}},
{"s1_army_car_radio_043","any",2,"reg=family|tmp=fresh|day=4,14|mood=angry|world=vehicle,door,window",{1,"You were running the car in the garage with the door shut? For the radio?",2,"Just ten minutes, to save the batteries",1,"You want to die of car exhaust with the infected outside? That'd be a real shame after all this",2,"I cracked the window"}},
{"s1_army_martial_law_044","any",2,"reg=civilian|tmp=fresh|day=2,6|mood=fear",{1,"Man on the radio said martial law, said it plain",2,"What's that mean for us, exactly?",1,"Means you don't argue with anybody holding a rifle, I reckon",2,"I wasn't planning to"}},
{"s1_army_signal_mirror_045","any",2,"reg=family|tmp=fresh|day=3,14|hour=9,17|mood=warm",{1,"I got my compact mirror, if a plane comes over, I'll flash it at 'em",2,"That's a makeup mirror",1,"It's a signal mirror now, it's been promoted"}},
{"s1_army_kentucky_only_046","any",3,"reg=civilian,family|tmp=fresh|day=1,5|mood=calm",{1,"Channel three said it's contained, said it's only here, only this county",2,"Contained, like a grease fire",3,"A grease fire, you put a lid on it",2,"Well, guess we're the pan"}},
{"s1_army_hear_engines_047","any",2,"reg=civilian|tmp=fresh|day=2,14|hour=5,9|mood=fear|world=vehicle,cars,road",{1,"Engines - big ones, on the road",2,"Army?",1,"Too loose, too loud, those are pickups with no mufflers",2,"Then get down, it's not the Army"}},
{"s1_army_rescue_list_048","any",2,"reg=civilian|tmp=fresh|day=4,14|mood=sad",{1,"I wrote down everybody I'm looking for, for when the Red Cross gets here with their tables",2,"How many?",1,"Eleven, my brother, his kids, my ex-wife, front and back of the page",2,"Put me on there, somebody should be looking for me too"}},
{"s1_army_louisville_fell_049","any",3,"reg=civilian,family|tmp=fresh|day=6,14|mood=grim",{1,"Still want to go to Louisville?",2,"I don't want to talk about Louisville",3,"He's just asking",2,"And I'm just not talking about it, I had a whole life in Louisville"}},
{"s1_army_mutter_green_050","any",1,"reg=civilian,family|tmp=fresh|day=2,14|mood=fear|world=cars,road",{1,"Any day now, boys in green coming up the road in those big trucks",1,"Clipboards - blankets, somebody with a real doctor's bag",1,"Any day now, sure, any day at all"}},
{"s1_army_crossed_out_051","any",2,"reg=family|tmp=fresh|day=7,14|mood=sad",{1,"Why'd you take the calendar down?",2,"I was crossing off days waiting on the Army",1,"And?",2,"And your daddy's birthday was the next square, I wasn't about to put an X on that one"}},
}
